def render(page: str, base: str):
    title, content = PAGES[page]
    safe_base = escape(base, quote=True)
    # Only fixed authored markup is substituted; account/provider data is
    # rendered by JS with textContent, never inserted into HTML.
    content = content.replace('{base}', safe_base)
    return f'''<!doctype html><html lang="ru" data-base="{safe_base}"><head>
      <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
      <title>{escape(title)} — Call Translator</title><link rel="stylesheet" href="{safe_base}/assets/site.css">
      <script src="{safe_base}/assets/site.js" defer></script></head><body>
      <header><a class="brand" href="{safe_base}/">Call<span>Translator</span></a><nav aria-label="Основная навигация">
      <a href="{safe_base}/install">Установка</a><a href="{safe_base}/pricing">Время речи</a><a href="{safe_base}/account">Кабинет ↗</a></nav></header>
      <main>{content}</main><footer><span>Call Translator · Техническая версия</span><nav aria-label="Информация">
      <a href="{safe_base}/privacy">Конфиденциальность</a><a href="{safe_base}/terms">Условия</a><a href="{safe_base}/support">Поддержка</a></nav></footer></body></html>'''
